INSERT INTO tp_exams (exam_code, kind, title, subtitle, description, difficulty, time_limit_sec, status, created_by) VALUES
('TP-PRACTICE-2026-MINI','PRACTICE','TOEFL iBT Practice — Mini Set (2026 Format)','Reading · Listening · Writing · Speaking','A short practice set modeled on the January 2026 TOEFL iBT structure: Reading (Complete the Words / Read in Daily Life / Read an Academic Passage), Listening (Listen and Choose a Response / Conversation / Announcement), Writing (Build a Sentence / Write an Email), Speaking (Listen and Repeat / Take an Interview). Auto-scored items are reported as a TestPrep internal band estimate — not an official ETS score.',NULL,1800,'PUBLISHED','system'),
('TP-VOCAB-EASY','VOCAB','Vocabulary Quiz — Easy','Word meanings · Reverse lookup · Context blanks','Core academic words. Multiple choice with instant scoring.', 'EASY',600,'PUBLISHED','system'),
('TP-VOCAB-MEDIUM','VOCAB','Vocabulary Quiz — Medium','Word meanings · Reverse lookup · Context blanks','Mid-level academic words. Multiple choice with instant scoring.','MEDIUM',600,'PUBLISHED','system'),
('TP-VOCAB-HARD','VOCAB','Vocabulary Quiz — Hard','Word meanings · Reverse lookup · Context blanks','Advanced academic words. Multiple choice with instant scoring.','HARD',600,'PUBLISHED','system');
INSERT INTO tp_questions (exam_id, section, task_type, prompt, body_text, audio_mode, choices_json, answer_key, auto_score, explanation, order_no) VALUES
(1,'READING','COMPLETE_THE_WORDS','Complete the missing letters of the word: uni_ _ rsity',NULL,'NONE','["ve","ls","ky","tz"]','A',1,'university — the missing pair is "ve".',1),
(1,'READING','COMPLETE_THE_WORDS','Complete the missing letters of the word: eco_ _ omy',NULL,'NONE','["na","no","mo","le"]','B',1,'economy — the missing pair is "no".',2),
(1,'READING','COMPLETE_THE_WORDS','Complete the missing letters of the word: det_ _ rmined',NULL,'NONE','["po","ma","mi","tu"]','C',1,'determined — the missing pair is "mi".',3),
(1,'READING','READ_DAILY_LIFE','Read the notice and answer the question.','CAMPUS DINING NOTICE — Starting Monday, all meal plans include one free late-night meal per week, valid between 9:00 p.m. and 11:00 p.m. on weekdays only. Weekend meals are not included.','NONE','["It may be used at 10:00 p.m. on Friday.","It may be used at 10:00 p.m. on Sunday.","It must be paid for in advance.","It can be used twice per week."]','A',1,'The free meal is valid 9–11 p.m. on weekdays; Friday 10 p.m. qualifies, weekends do not.',4),
(1,'READING','READ_DAILY_LIFE','Read the message and answer the question.','GROUP CHAT — Maya: "Lab report due Thursday 5 p.m. Team, upload your data tables to the shared folder by Wednesday noon so I can format everything in one pass." — Leo: "Got it. I will finish my part tonight."','NONE','["Wednesday noon","Wednesday evening","Thursday noon","Friday morning"]','A',1,'Leo''s and Maya''s deadline for uploads is Wednesday noon; the report itself is due Thursday 5 p.m.',5),
(1,'READING','READ_DAILY_LIFE','Read the email and answer the question.','LIBRARY EMAIL — Your item "Urban Ecology" was due on October 3 and has not been returned. A fine of $0.50 per day accrues automatically. If you renewed the item before its due date, please disregard this message; our system updates may lag by up to two business days.','NONE','["The fine may be wrong if the book was renewed on time.","The fine stops after two days.","The book must be returned this week only.","The reader should pay before renewing."]','A',1,'The email states renewals before the due date invalidate the notice, subject to a system lag.',6),
(1,'READING','READ_PASSAGE','Read the passage and answer questions 7–8.','Coral reefs cover less than one percent of the ocean floor yet support roughly a quarter of all marine species. This disparity is explained by the structure reefs provide: a three-dimensional habitat with countless niches. When water temperatures rise beyond a narrow tolerance range, corals expel the symbiotic algae that supply most of their energy, a process known as bleaching. Bleached corals are not dead, and they can recover if conditions normalize quickly enough. Prolonged warm periods, however, shift the balance from recovery to mortality, and repeated events simplify the reef structure, reducing the number of available niches and the biodiversity they supported.','NONE','["Most marine species live on coral reefs.","Reefs host a disproportionate share of marine species relative to their area.","Reefs cover about a quarter of the ocean floor.","The diversity of reef species is mostly random."]','B',1,'The passage contrasts <1% of area with about 25% of species — a disproportionate share.',7),
(1,'READING','READ_PASSAGE','Based on the passage, the word "expel" in the passage is closest in meaning to:',NULL,'NONE','["absorb","distribute","drive out","transform"]','C',1,'Bleaching occurs when corals drive out their symbiotic algae; "expel" = "drive out".',8),
(1,'LISTENING','LISTEN_RESPONSE','Listen to the question and choose the best response.','Our research group meets on Tuesdays. Would you like to join us?','TTS','["Yes, it sounds interesting.","On the second floor, next to the lab.","The printer is out of paper.","It was founded in 1998."]','A',1,'An invitation is best answered with acceptance or decline; option A responds directly.',9),
(1,'LISTENING','LISTEN_RESPONSE','Listen to the question and choose the best response.','How did you manage to finish the survey so quickly?','TTS','["By sending reminders to every participant.","About three hundred responses.","In the main building.","I am fine, thanks."]','A',1,'The question asks about method; only the "By..." answer explains how.',10),
(1,'LISTENING','LISTEN_RESPONSE','Listen to the question and choose the best response.','Is the statistics lecture really starting next week?','TTS','["It''s a really long course.","No, it was moved to the week after.","Yes, fifty students at a time.","Around ten dollars."]','B',1,'A yes/no question about timing needs a confirmation or correction; B corrects the date.',11),
(1,'LISTENING','LISTEN_CONVERSATION','Listen to the conversation and answer the question.','Woman: I booked a study room for two hours, but our project meeting only needs one hour now. Can I change the reservation? — Man: Yes, but the system only allows reductions on the same day the room is used. If it''s for tomorrow, you will need to cancel and rebook.','TTS','["She must wait until the day of use to shorten it.","He will shorten it for her automatically.","She has to pay for two hours no matter what.","The reservation cannot be changed at all."]','A',1,'Reductions are allowed only on the day of use; for tomorrow she must cancel and rebook.',12),
(1,'LISTENING','LISTEN_CONVERSATION','Listen to the conversation and answer the question.','Student: Do you have a copy of last week''s astronomy reading? Mine has diagrams I could not see clearly. — Librarian: The scanned copy is fine, but it is only available on the computer in room 214 for copyright reasons. You can take notes there.','TTS','["Room 214.","The library website.","Her own copy.","The course syllabus."]','A',1,'The scan is available only on the computer in room 214.',13),
(1,'LISTENING','LISTEN_ANNOUNCEMENT','Listen to the announcement and answer the question.','Good evening. A water main repair will shut off water on the fourth floor of the science building from ten tonight until six tomorrow morning. Lab sessions scheduled before noon are cancelled; make-up sessions will be posted on the department board. The rest of the building will operate normally.','TTS','["Morning lab sessions in the science building","All classes campus-wide","Water repair in the dormitory","Evening lab sessions"]','A',1,'Only labs before noon in the affected building are cancelled.',14),
(1,'WRITING','BUILD_SENTENCE','Put the words in the correct order to form one grammatical sentence.',NULL,'NONE','["must","The","be","quiet","students","in","the","library"]','the students must be quiet in the library',1,'English declarative order: subject (The students) + modal verb phrase (must be quiet) + place (in the library).',15),
(1,'WRITING','WRITE_EMAIL','Write an email to your professor (about 50–80 words) explaining that you must miss Thursday''s class and asking how to make up the in-class quiz. Do not forget to greet the professor and sign your name.',NULL,'NONE',NULL,NULL,0,'This item is saved for manual review. TestPrep does not auto-score writing; aim for a clear purpose, polite tone, and complete sentences.',16),
(1,'SPEAKING','SPEAK_REPEAT','Listen to the sentence and repeat it aloud as clearly as possible. Record your answer.','The observatory will remain closed until the road is cleared.','TTS',NULL,NULL,0,'Recorded for manual review. Repeat with natural stress and complete words.',17),
(1,'SPEAKING','SPEAK_INTERVIEW','Answer the interview question aloud (about 30–45 seconds). Record your answer.','Some universities require first-year students to live in campus housing. Others allow them to live wherever they choose. Which policy do you think is better, and why?','NONE',NULL,NULL,0,'Recorded for manual review. State a position, give reasons, and add one example.',18);
INSERT INTO tp_questions (exam_id, section, task_type, prompt, body_text, audio_mode, choices_json, answer_key, auto_score, explanation, order_no) VALUES
(2,'VOCAB','VOCAB_E2S','Choose the meaning of the word: significant','The study found a significant difference between the two groups.','NONE','["small and unnoticeable","important or large enough to matter","regular and expected","temporary"]','B',1,'"significant" = important or big enough to be worth attention.',1),
(2,'VOCAB','VOCAB_S2E','Choose the word that means: to produce or create something','Researchers hope to ____ new data by surveying more schools.','NONE','["generate","remember","pretend","separate"]','A',1,'"generate" means to produce or create.',2),
(2,'VOCAB','VOCAB_E2S','Choose the meaning of the word: accurate','Only one of the estimates was accurate.','NONE','["careless","happening often","correct and careful","expensive"]','C',1,'"accurate" = correct and precise.',3),
(2,'VOCAB','VOCAB_S2E','Choose the word that means: to keep something in its current state','Plants need water to ____ their growth.','NONE','["forget","maintain","destroy","divide"]','B',1,'"maintain" = to keep in the same condition.',4),
(2,'VOCAB','VOCAB_E2S','Choose the meaning of the word: obvious','It was obvious that the experiment had failed.','NONE','["hard to explain","easy to see or understand","slightly risky","officially approved"]','B',1,'"obvious" = easy to notice or understand.',5),
(2,'VOCAB','VOCAB_S2E','Choose the word that means: to become larger or wider','Metal will ____ when it is heated.','NONE','["expand","freeze","vanish","darken"]','A',1,'"expand" = to grow larger in size or range.',6),
(2,'VOCAB','VOCAB_CLOZE','Choose the word that best completes the sentence.','The two results are not ____; one is based on ten students, the other on a thousand.','NONE','["obvious","significant","separate","temporary"]','B',1,'Sample size makes the difference "significant" (worth attention), not merely obvious.',7),
(2,'VOCAB','VOCAB_CLOZE','Choose the word that best completes the sentence.','The machine can ____ up to 200 reports per hour.','NONE','["maintain","generate","expand","observe"]','B',1,'Producing reports = "generate".',8);
INSERT INTO tp_questions (exam_id, section, task_type, prompt, body_text, audio_mode, choices_json, answer_key, auto_score, explanation, order_no) VALUES
(3,'VOCAB','VOCAB_E2S','Choose the meaning of the word: comprehensive','The review offers a comprehensive view of the field.','NONE','["including almost everything needed","short and quick","based on opinion","newly written"]','A',1,'"comprehensive" = complete, covering many elements.',1),
(3,'VOCAB','VOCAB_S2E','Choose the word that means: to make an action easier','The tutor''s notes ____ understanding of the theory.','NONE','["facilitate","forbid","imagine","replace"]','A',1,'"facilitate" = to make easier.',2),
(3,'VOCAB','VOCAB_E2S','Choose the meaning of the word: hypothesis','The experiment was designed to test a single hypothesis.','NONE','["a proven law","a testable explanation","an unrelated detail","a final conclusion"]','B',1,'A hypothesis is a proposed, testable explanation.',3),
(3,'VOCAB','VOCAB_S2E','Choose the word that means: done before the main work begins','A ____ report outlined the methods last month.','NONE','["preliminary","permanent","perfect","popular"]','A',1,'"preliminary" = introductory, done before the main stage.',4),
(3,'VOCAB','VOCAB_E2S','Choose the meaning of the word: subtle','The difference between the two paintings is subtle.','NONE','["large and bold","delicate and hard to notice","incorrect","public"]','B',1,'"subtle" = slight, difficult to detect.',5),
(3,'VOCAB','VOCAB_S2E','Choose the word that means: to limit or control','The new rules ____ how many books a member may borrow.','NONE','["restrict","encourage","translate","collect"]','A',1,'"restrict" = to limit.',6),
(3,'VOCAB','VOCAB_CLOZE','Choose the word that best completes the sentence.','Before drawing conclusions, the team gathered ____ data to test each ____ .','NONE','["hypothesis ... limit","preliminary ... subtle","empirical ... hypothesis","comprehensive ... rule"]','C',1,'Data that tests a hypothesis is "empirical" — based on observation.',7),
(3,'VOCAB','VOCAB_CLOZE','Choose the word that best completes the sentence.','The campus map gives a ____ overview of every building.','NONE','["subtle","comprehensive","preliminary","restrictive"]','B',1,'Covering every building = "comprehensive".',8);
INSERT INTO tp_questions (exam_id, section, task_type, prompt, body_text, audio_mode, choices_json, answer_key, auto_score, explanation, order_no) VALUES
(4,'VOCAB','VOCAB_E2S','Choose the meaning of the word: alleviate','The program aims to alleviate student debt.','NONE','["to make less severe","to measure exactly","to hide completely","to hand out"]','A',1,'"alleviate" = to lessen (a problem or burden).',1),
(4,'VOCAB','VOCAB_S2E','Choose the word that means: to support with evidence','A second study ____ the first result.','NONE','["alleviates","corroborates","inherents","terminates"]','B',1,'"corroborate" = to confirm with supporting evidence.',2),
(4,'VOCAB','VOCAB_E2S','Choose the meaning of the word: empirical','The claim lacks empirical support.','NONE','["based on observation or data","based on tradition","based on opinion","based on law"]','A',1,'"empirical" = grounded in observed evidence.',3),
(4,'VOCAB','VOCAB_S2E','Choose the word that means: existing as a natural part of something','Risk is ____ to any research project.','NONE','["paradigmatic","empirical","inherent","alleviated"]','C',1,'"inherent" = built in, naturally part of.',4),
(4,'VOCAB','VOCAB_E2S','Choose the meaning of the word: paradigm','The discovery shifted the prevailing paradigm.','NONE','["a small correction","a typical model or framework of thought","a legal ruling","a repeated experiment"]','B',1,'A paradigm is a dominant framework or model.',5),
(4,'VOCAB','VOCAB_S2E','Choose the word that means: to examine very closely','Reviewers ____ every figure in the paper.','NONE','["scrutinize","generate","alleviate","maintain"]','A',1,'"scrutinize" = to inspect with great care.',6),
(4,'VOCAB','VOCAB_CLOZE','Choose the words that best complete the sentence.','The committee will ____ the budget line by line before the new funding ____ is approved.','NONE','["scrutinize ... paradigm","alleviate ... hypothesis","empirical ... restriction","generate ... corroboration"]','A',1,'The committee inspects closely ("scrutinize") the funding framework ("paradigm") it approves.',7),
(4,'VOCAB','VOCAB_CLOZE','Choose the words that best complete the sentence.','____ evidence, collected over ten years, ____ the concerns of families by showing the program''s real benefits.','NONE','["Empirical ... alleviates","Inherent ... corroborates","Subtle ... restricts","Preliminary ... generates"]','A',1,'Long-term collected evidence is "empirical", and showing benefits "alleviates" concerns.',8);
